import React from "react";
import {
  AbsoluteFill,
  Easing,
  Sequence,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// Semua gambar sudah tertanam di file ini (tidak perlu unggah gambar terpisah)
const IMG_AKUR = "data:image/jpeg;base64,";
const IMG_RIBUT = "data:image/jpeg;base64,";
const IMG_KADES = "data:image/jpeg;base64,";
const IMG_PROGRAM = "data:image/jpeg;base64,";

const W = 1080;
const H = 1920;
const LW = 1080;
const LH = Math.round((LW * 2528) / 1696); // tinggi gambar saat lebar pas layar

type Key = { t: number; x: number; y: number; z: number };
type SceneDef = { img: string; start: number; end: number; cam: Key[] };

// Adegan (detik). Kamera: t = detik dalam adegan, x/y = titik fokus (0-1), z = zoom
const SCENES: SceneDef[] = [
  {
    img: IMG_AKUR,
    start: 0,
    end: 13,
    cam: [
      { t: 0, x: 0.5, y: 0.5, z: 1.0 },
      { t: 2, x: 0.5, y: 0.5, z: 1.0 },
      { t: 5, x: 0.55, y: 0.45, z: 1.6 },
      { t: 9, x: 0.55, y: 0.82, z: 1.5 },
      { t: 13, x: 0.5, y: 0.5, z: 1.05 },
    ],
  },
  {
    img: IMG_RIBUT,
    start: 13,
    end: 29,
    cam: [
      { t: 0, x: 0.5, y: 0.5, z: 1.0 },
      { t: 4, x: 0.6, y: 0.55, z: 1.5 },
      { t: 7, x: 0.6, y: 0.4, z: 1.7 },
      { t: 12, x: 0.8, y: 0.2, z: 1.8 },
      { t: 16, x: 0.5, y: 0.55, z: 1.1 },
    ],
  },
  {
    img: IMG_KADES,
    start: 29,
    end: 44.5,
    cam: [
      { t: 0, x: 0.5, y: 0.5, z: 1.0 },
      { t: 4, x: 0.5, y: 0.5, z: 1.1 },
      { t: 8, x: 0.35, y: 0.6, z: 1.5 },
      { t: 12, x: 0.82, y: 0.62, z: 1.9 },
      { t: 15.5, x: 0.5, y: 0.55, z: 1.1 },
    ],
  },
  {
    img: IMG_PROGRAM,
    start: 44.5,
    end: 59,
    cam: [
      { t: 0, x: 0.5, y: 0.5, z: 1.0 },
      { t: 4, x: 0.25, y: 0.4, z: 1.5 },
      { t: 9, x: 0.8, y: 0.35, z: 1.8 },
      { t: 14.5, x: 0.5, y: 0.55, z: 1.0 },
    ],
  },
];

// Narasi (teks muncul kata per kata), detik global
const LINES = [
  { s: 0.3, e: 7, text: "Dulu, kampung kita adem. Warga ngopi bareng di warkop, ketawa bareng, saling ambil gorengan." },
  { s: 7, e: 13, text: "Beda pilihan? Nggak masalah. Yang penting rukun terus." },
  { s: 13, e: 17.5, text: "Tapi begitu pilkades datang, semuanya berubah." },
  { s: 17.5, e: 22, text: "Tim satu, tim dua, semua merasa paling benar." },
  { s: 22, e: 28.5, text: "Saling tuding, saling sindir, sampai dibilang hoaks dan dibayar." },
  { s: 29, e: 33.5, text: "Terus, setelah hasilnya disahkan, apa yang terjadi?" },
  { s: 33.5, e: 38.5, text: "Yang menang duduk manis, ngopi santai di ruangan ber-AC." },
  { s: 38.5, e: 44.5, text: "Sementara warga yang dulu dibela mati-matian, menunggu di luar pintu. Kita pun dilupakan." },
  { s: 44.5, e: 50, text: "Makanya, lain kali bela programnya, bukan orangnya." },
  { s: 50, e: 55, text: "Air bersih, jalan bagus, bantuan tani, itu yang kita butuhkan." },
  { s: 55, e: 58.8, text: "Boleh beda pilihan, jangan sampai jadi musuhan." },
];

const ease = Easing.inOut(Easing.cubic);
const FADE = 10; // frame untuk transisi antar adegan

export const Video: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const t = frame / fps;

  const line = LINES.find((l) => t >= l.s && t < l.e);
  const fadeAll = interpolate(frame, [0, 12, durationInFrames - 15, durationInFrames], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#000", overflow: "hidden" }}>
      <div style={{ opacity: fadeAll, width: W, height: H, position: "relative" }}>
        {SCENES.map((sc, idx) => {
          const from = Math.round(sc.start * fps);
          const last = idx === SCENES.length - 1;
          const dur = Math.round((sc.end - sc.start) * fps) + (last ? 0 : FADE);
          return (
            <Sequence key={idx} from={from} durationInFrames={dur}>
              <Scene sc={sc} first={idx === 0} />
            </Sequence>
          );
        })}

        {/* bayangan bawah supaya teks mudah dibaca */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            height: 700,
            background: "linear-gradient(to top, rgba(0,0,0,0.75), rgba(0,0,0,0))",
          }}
        />

        {line && <Caption line={line} frame={frame} fps={fps} />}
        <Watermark />
      </div>
    </AbsoluteFill>
  );
};

const Scene: React.FC<{ sc: SceneDef; first: boolean }> = ({ sc, first }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const cam = sc.cam;

  let i = 0;
  for (let k = 0; k < cam.length - 1; k++) {
    if (t >= cam[k].t) i = k;
  }
  const a = cam[i];
  const b = cam[Math.min(i + 1, cam.length - 1)];
  const p = interpolate(t, [a.t, b.t], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: ease,
  });
  const drift = 1 + 0.012 * Math.sin(t * 0.9);
  const z = (a.z + (b.z - a.z) * p) * drift;
  const fx = a.x + (b.x - a.x) * p;
  const fy = a.y + (b.y - a.y) * p;

  let tx = W / 2 - fx * LW * z;
  let ty = H / 2 - fy * LH * z;
  if (LW * z >= W) tx = Math.min(0, Math.max(W - LW * z, tx));
  else tx = (W - LW * z) / 2;
  if (LH * z >= H) ty = Math.min(0, Math.max(H - LH * z, ty));
  else ty = (H - LH * z) / 2;

  const opacity = first
    ? 1
    : interpolate(frame, [0, FADE], [0, 1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ opacity }}>
      {/* latar buram untuk mengisi ruang kosong atas/bawah */}
      <img
        src={sc.img}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: W,
          height: H,
          objectFit: "cover",
          filter: "blur(40px) brightness(0.55)",
          transform: "scale(1.2)",
        }}
      />
      <img
        src={sc.img}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: LW,
          height: LH,
          transformOrigin: "0 0",
          transform: `translate(${tx}px, ${ty}px) scale(${z})`,
        }}
      />
    </AbsoluteFill>
  );
};

const Watermark: React.FC = () => (
  <div
    style={{
      position: "absolute",
      top: 56,
      left: 0,
      right: 0,
      display: "flex",
      justifyContent: "center",
    }}
  >
    <div
      style={{
        padding: "12px 30px",
        borderRadius: 40,
        background: "rgba(0,0,0,0.55)",
        border: "2px solid rgba(255,255,255,0.35)",
        fontFamily: "Arial, Helvetica, sans-serif",
        fontSize: 34,
        color: "#FFFFFF",
        letterSpacing: 1,
      }}
    >
      supported by <b style={{ color: "#FFD600", letterSpacing: 2 }}>NUYAPAY</b>
    </div>
  </div>
);

const Caption: React.FC<{
  line: { s: number; e: number; text: string };
  frame: number;
  fps: number;
}> = ({ line, frame, fps }) => {
  const words = line.text.split(" ");
  const start = line.s * fps;
  const span = (line.e - line.s) * fps * 0.85;
  const step = span / words.length;

  let current = 0;
  words.forEach((_, idx) => {
    if (frame >= start + idx * step) current = idx;
  });

  return (
    <div
      style={{
        position: "absolute",
        left: 50,
        right: 50,
        bottom: 150,
        textAlign: "center",
        fontFamily: "Arial Black, Impact, Helvetica, sans-serif",
        fontWeight: 900,
        fontSize: 64,
        lineHeight: 1.25,
      }}
    >
      {words.map((w, idx) => {
        const at = start + idx * step;
        if (frame < at) return null;
        const pop = interpolate(frame, [at, at + 6], [0.7, 1], {
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.back(2)),
        });
        const isCur = idx === current;
        return (
          <span
            key={idx}
            style={{
              display: "inline-block",
              marginRight: 16,
              transform: `scale(${pop})`,
              color: isCur ? "#FFD600" : "#FFFFFF",
              WebkitTextStroke: "10px #000",
              paintOrder: "stroke fill",
              textShadow: "0 6px 14px rgba(0,0,0,0.6)",
            }}
          >
            {w}
          </span>
        );
      })}
    </div>
  );
};
